import java.util.ArrayList;
import java.util.List;

interface Notifier {
    /** Delivers the message; must not throw for empty text. */
    void send(String message);
}

class MemoryNotifier implements Notifier {          // for tests.
    final List<String> sent = new ArrayList<>();
    public void send(String message) { sent.add(message); }
}

class ConsoleNotifier implements Notifier {         // for development.
    public void send(String message) { System.out.println("NOTIFY: " + message); }
}

class OrderService {
    private final Notifier notifier;                 // depends on the interface.
    OrderService(Notifier notifier) { this.notifier = notifier; }
    void place(String item) { notifier.send("Ordered " + item); }
}

public class Shop {
    public static void main(String[] args) {
        MemoryNotifier memory = new MemoryNotifier();
        new OrderService(memory).place("pen");
        System.out.println(memory.sent);                          // [Ordered pen]
        new OrderService(new ConsoleNotifier()).place("ink");     // NOTIFY: Ordered ink
    }
}
